@startuml

class Location {
  + Address : string
}

class Driver {
  + FirstName : string
  + LastName : string
}

class Vehicle {
  + VehicleNumber : string
}

class Truck {
  + Weight : float
}

class Car {
  + NumberOfSeats : int
}

class Van {}

class Order {
  + OriginLocation : string
  + DestinationLocation : string
  + ExecutionDate : date
}

Location "1" *-- "1..*" Driver
Location "1" *-- "1..*" Vehicle
Vehicle "1" --|> Truck
Vehicle "1" --|> Car
Vehicle "1" --|> Van
Order "*" -- "1" Driver : carriedBy
Driver "1" -- "0..1" Order : assignedTo
Driver "1" -- "0..1" Vehicle : drives

@enduml

